// These are title-static Dynasty bootstrap contracts extracted from the supplied
// successful capture. They contain no account, profile, league, or session data.
//
//go:embed fixtures/dynasty-531-reply.bin
var dynasty531Payload []byte

//go:embed fixtures/dynasty-301-reply.bin
var dynasty301Payload []byte

//go:embed fixtures/dynasty-1261-reply.bin
var dynasty1261Payload []byte

// These payloads are static title settings schemas from the successful clean-room
// capture. They contain no account identity or authentication material. Replaying
// the complete schema is required because the client indexes named settings while
// building the online front end and does not accept an empty collection.
func capturedSettingsPayloads() map[route][]byte {
	return map[route][]byte{
		{ComponentSettings, 1}:      mustDecodeCapturedPayload(settingsDefinitionsPayloadB64),
		{ComponentSettings, 2}:      mustDecodeCapturedPayload(settingsGroupsPayloadB64),
		{ComponentOSDK, 1000}:       mustDecodeCapturedPayload(osdkRecommendationsPayloadB64),
		{ComponentBootStatus, 531}:  dynasty531Payload,
		{ComponentBootStatus, 301}:  dynasty301Payload,
		{ComponentBootStatus, 1261}: dynasty1261Payload,
	}
}

func mustDecodeCapturedPayload(value string) []byte {
	payload, err := base64.StdEncoding.DecodeString(value)
	if err != nil {
		panic(err)
	}
	return payload
}

